INSERT OR IGNORE INTO content_versions (id,record_id,version_number,payload_json,change_summary,source_id) VALUES ('version_seed_project-next-ingenium','project-next-ingenium',1,'{"id":"project-next-ingenium","slug":"next-ingenium","title":"Next INGENIUM","type":"project","subtype":"Next Erasmus+ alliance phase","studentSummary":"The funded next phase aims to deepen academic, legal and operational integration through December 2028.","status":"Upcoming","availability":"Funding selected in July 2026; the exact operational start date is not stated","universityIds":["university-uniovi","university-mus","university-uoc","university-hka","university-xamk","university-uda","university-hs","university-mtu","university-urn","university-tuiasi"],"hostUniversityId":"university-uniovi","themes":["Alliance integration","European Campus","Mobility","Joint education"],"endDate":"2028-12-31","funding":"Approximately €7.2 million in Erasmus+ support","whyItMatters":"Published targets include seven joint programmes with enrolled students, more than twenty pathways, twenty micro-credentials, over one hundred catalogue courses and about three thousand mobility experiences by end-2028.","actionLabel":"Read the funding announcement","officialUrl":"https://www.xamk.fi/en/ingenium-secures-two-more-years-of-erasmus-funding-for-its-next-phase","sourceId":"fc-next-ingenium-2026","confidence":"High","featured":true,"lastVerified":"2026-09-29","dataClassification":"verified","sourceIds":["fc-next-ingenium-2026"],"fullDescription":"The approximately €7.2 million bridge phase runs through December 2028. Published targets are seven joint programmes with enrolled students, more than 20 Pathways, 20 microcredentials, over 100 shared courses and about 3,000 mobility experiences. These are targets, not completed outcomes."}','Imported from the verified INGENIUM+ v1.5 dataset','fc-next-ingenium-2026');
