INSERT OR IGNORE INTO content_versions (id,record_id,version_number,payload_json,change_summary,source_id) VALUES ('version_seed_initiative-ingenium-egtc','initiative-ingenium-egtc',1,'{"id":"initiative-ingenium-egtc","slug":"ingenium-egtc","title":"INGENIUM European Grouping of Territorial Cooperation","shortTitle":"INGENIUM EGTC","type":"initiative","subtype":"Planned permanent legal entity","studentSummary":"INGENIUM is preparing an EGTC to give the alliance legal personality for contracts, staffing, property and direct funding access.","status":"Under development","availability":"Registration was reported in progress in Finland; no final registration date was verified by the research cut-off","universityIds":["university-uniovi","university-mus","university-uoc","university-hka","university-xamk","university-uda","university-hs","university-mtu","university-urn","university-tuiasi"],"hostUniversityId":"university-xamk","countries":["Finland"],"themes":["Governance","Legal entity","Long-term sustainability"],"actionLabel":"Read the official status update","officialUrl":"https://www.xamk.fi/en/ingenium-secures-two-more-years-of-erasmus-funding-for-its-next-phase","sourceId":"fc-next-ingenium-2026","confidence":"High","lastVerified":"2026-09-29","dataClassification":"verified","sourceIds":["fc29-annual-education-call","fc-full-rouen-council","fc-full-d101"],"fullDescription":"The EGTC is intended to provide a durable legal and operational vehicle for joint staffing, funding, representation, education coordination and future European degrees. Governance reports describe registration work in Finland, but a completed legal-registration notice was not found."}','Imported from the verified INGENIUM+ v1.5 dataset','fc-next-ingenium-2026');
