INSERT OR IGNORE INTO content_versions (id,record_id,version_number,payload_json,change_summary,source_id) VALUES ('version_seed_project-bi4e','project-bi4e',1,'{"id":"project-bi4e","slug":"boosting-ingenium-for-excellence","title":"Boosting INGENIUM for Excellence","shortTitle":"BI4E","type":"project","subtype":"Horizon Europe institutional-transformation project","studentSummary":"A Horizon Europe project that strengthened research, innovation, governance, technology transfer and academic careers across eight INGENIUM institutions.","fullDescription":"Project 101071321 ran from October 2022 through September 2025. Public outputs include institutional-transformation guidance, research-support policy, entrepreneurship and innovation-service resources, a technology-transfer-office network, talent studies, staff training and the CONNECT researcher-matching platform. Its eight-institution consortium is narrower than the ten-member alliance.","status":"Completed","availability":"Project results are public through CORDIS","universityIds":["university-tuiasi","university-hka","university-hs","university-mus","university-mtu","university-uda","university-urn"],"hostUniversityId":"university-tuiasi","themes":["Research","Innovation","Institutional transformation","Technology transfer"],"startDate":"2022-10-01","endDate":"2025-09-30","dateLabel":"October 2022–September 2025","actionLabel":"Read the CORDIS results","officialUrl":"https://cordis.europa.eu/project/id/101071321/reporting","sourceId":"fc-full-bi4e-cordis","workPackage":"Horizon Europe project 101071321","featured":true,"lastVerified":"2026-09-29","confidence":"High","dataClassification":"verified","sourceIds":["fc-full-bi4e-cordis"]}','Imported from the verified INGENIUM+ v1.5 dataset','fc-full-bi4e-cordis');
