INSERT OR IGNORE INTO content_versions (id,record_id,version_number,payload_json,change_summary,source_id) VALUES ('version_seed_module-digital-wellbeing-2024','module-digital-wellbeing-2024',1,'{"id":"module-digital-wellbeing-2024","slug":"digital-wellbeing-shared-module-2024","title":"Digital Wellbeing — First Shared INGENIUM Module","type":"module","subtype":"Blended shared module pilot","studentSummary":"The alliance’s first shared module combined online learning with an intensive week at MTU and tested common academic and digital-delivery processes.","fullDescription":"Development began in November 2023. Online lectures started in September 2024, followed by a week at Munster Technological University in October and completion in December. The 5-ECTS pilot involved 20 staff and 40 students across disciplines, used the INGENIUM Moodle platform and produced reusable resources for partner delivery.","status":"Completed","availability":"Historical pilot and reusable learning resources","universityIds":["university-mtu","university-hka","university-xamk","university-hs","university-uoc","university-mus","university-uniovi","university-urn","university-uda","university-tuiasi"],"hostUniversityId":"university-mtu","countries":["Ireland"],"city":"Cork","themes":["Digital wellbeing","Shared education","Blended learning"],"deliveryMode":"Blended","mobilityType":"Online lectures plus one physical intensive week","startDate":"2024-09-01","endDate":"2024-12-31","dateLabel":"September–December 2024","ects":5,"capacity":"40 students and 20 staff","actionLabel":"Read the module outcome","officialUrl":"https://ingenium-university.eu/the-first-ingenium-shared-module-digital-wellbeing-a-milestone-for-the-alliance/","sourceId":"fc-full-digital-wellbeing","lastVerified":"2026-09-29","confidence":"High","dataClassification":"verified","sourceIds":["fc-full-digital-wellbeing"]}','Imported from the verified INGENIUM+ v1.5 dataset','fc-full-digital-wellbeing');
