INSERT OR IGNORE INTO content_versions (id,record_id,version_number,payload_json,change_summary,source_id) VALUES ('version_seed_microcredential-towards-framework-2026','microcredential-towards-framework-2026',1,'{"id":"microcredential-towards-framework-2026","slug":"towards-ingenium-microcredentials-framework-2026","title":"Towards INGENIUM Micro-credentials Framework","type":"microcredential","subtype":"First joint INGENIUM microcredential","studentSummary":"The first joint alliance microcredential trained staff to design, manage and certify joint microcredentials through the INGENIUM Education Platform.","fullDescription":"The pilot was jointly developed by Oviedo, Xamk and Crete. It combined asynchronous content, quizzes, a multinational group proposal and peer review, and demonstrated final digital certification through Europass.","status":"Completed","availability":"The first edition ran online from 11 May to 30 June 2026","universityIds":["university-uniovi","university-xamk","university-uoc"],"hostUniversityId":"university-uniovi","themes":["Microcredentials","Staff development","Digital credentials"],"deliveryMode":"Virtual","startDate":"2026-05-11","endDate":"2026-06-30","applicationOpenDate":"2026-04-27","applicationDeadline":"2026-05-03","dateLabel":"11 May–30 June 2026","ects":1,"workload":"25 hours: 14 teaching and 11 group work","eligibility":"Academic and administrative staff at INGENIUM universities, plus eligible external partners","capacity":"50","actionLabel":"Read the pilot record","officialUrl":"https://ingenium-university.eu/courses/towards-ingenium-micro-credentials-framework/","sourceId":"fc-full-first-microcredential","lastVerified":"2026-10-01","confidence":"High","dataClassification":"verified","sourceIds":["fc-full-first-microcredential"]}','Imported from the verified INGENIUM+ v1.5 dataset','fc-full-first-microcredential');
